const level=i=>quick?8:state.levels[i];function cost(i){return Math.floor(100*Math.pow(1.65,state.levels[i])*(i===5?1.3:1))}function requirement(i){if(i===1&&state.levels[i]>=2&&level(0)<2)return 'Requires engine II';if(i===5&&state.levels[i]>=2&&level(2)<2)return 'Requires hull II';return null}
