function renderShop(){ $('branches').innerHTML=branchNames.map((n,i)=>`<div class="branch"><h3>${n}</h3><div class="tiers">${'▰'.repeat(level(i))}${'▱'.repeat(8-level(i))}</div><p>${desc[i]}</p><button data-buy="${i}">${level(i)>=8?'COMPLETE':requirement(i)||('UPGRADE · '+cost(i)+' Fe')}</button></div>`).join('');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(+b.dataset.buy));$('reset').hidden=!quick}
function buy(i){if(quick||level(i)>=8||requirement(i)||state.money<cost(i)){audio(50,.15);return false}state.money-=cost(i);state.levels[i]++;visuals();renderShop();save();audio(420,.5,'triangle');notify(branchNames[i]+' '+state.levels[i]);return true}
visuals();function toggleShop(){ $('panel').hidden=!$('panel').hidden;if(!$('panel').hidden)renderShop()}
$('upgrades').onclick=toggleShop;$('close').onclick=toggleShop;$('mode').onclick=()=>{quick=!quick;quickTime=180;score=0;formation();tug.position.set(0,0,20);boatVel.set(0,0,0);visuals();$('mode').textContent=quick?'MAIN HARBOR ↗':'QUICK PLAY ↗';notify(quick?'180s · BREAK EVERYTHING':'THE QUEEN’S REACH');$('panel').hidden=true};$('reset').onclick=()=>{formation();notify('WRECK FIELD RESET')};$('build').onclick=()=>{rig=(rig+1)%3;$('build').textContent='RIG: '+['BALANCED','BULL · TORQUE','DART · SPEED'][rig]};$('project').onclick=()=>{if(state.money>=600&&!quick){state.money-=600;state.projects++;save();notify('FOUNDRY RESTORED ×'+state.projects);burst(foundry,80)}};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♫ ON':'♫ OFF'};
let quality='auto';function setQuality(q){quality=q;const v=q==='auto'?(navigator.hardwareConcurrency<=4?'low':'med'):q;renderer.setPixelRatio(Math.min(devicePixelRatio,v==='low'?.8:v==='med'?1.25:1.8));scene.fog.density=v==='low'?.010:.0085}setQuality('auto');$('quality').onchange=e=>setQuality(e.target.value.toLowerCase());
