if($('panel').hidden){const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),turn=(keys.KeyA||keys.ArrowLeft?1:0)-(keys.KeyD||keys.ArrowRight?1:0),boost=keys.ShiftLeft?1.8:1;const speed=boatVel.length();tug.rotation.y+=turn*dt*(1.15+speed*.025);const dir=new THREE.Vector3(Math.sin(tug.rotation.y),0,Math.cos(tug.rotation.y));boatVel.addScaledVector(dir,-forward*dt*(6+level(0)*1.8)*boost*(rig===2?1.4:rig===1?.7:1));boatVel.multiplyScalar(Math.pow(.72,dt));boatVel.clampLength(0,(10+level(0)*1.4)*boost);tug.position.addScaledVector(boatVel,dt);if(forward){started=true;wakeTick+=dt;if(wakeTick>.07){wakeTick=0;const w=wakes[wi++%60];w.p.copy(tug.position).addScaledVector(dir,4);w.p.y=.02;w.life=2}}}
